CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE membership_role AS ENUM ('owner','admin','moderator','member');
CREATE TYPE channel_kind AS ENUM ('text','voice','stage','theater');
CREATE TYPE media_status AS ENUM ('pending','processing','ready','rejected');
CREATE TYPE badge_tier AS ENUM ('wood','stone','iron','gold','diamond');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_provider_id text UNIQUE NOT NULL, username varchar(32) UNIQUE NOT NULL, display_name varchar(64) NOT NULL, avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE guilds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(80) NOT NULL, slug varchar(48) UNIQUE, description varchar(500), icon_url text, banner_url text, owner_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE guild_members (guild_id uuid NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role membership_role NOT NULL DEFAULT 'member', joined_at timestamptz NOT NULL DEFAULT now(), is_eligible boolean NOT NULL DEFAULT true, PRIMARY KEY(guild_id,user_id));
CREATE INDEX guild_members_eligible_count ON guild_members(guild_id) WHERE is_eligible=true;
CREATE TABLE channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, name varchar(80) NOT NULL, topic varchar(300), kind channel_kind NOT NULL DEFAULT 'text', position integer NOT NULL DEFAULT 0, is_private boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid NOT NULL REFERENCES channels(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 4000), reply_to uuid REFERENCES messages(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz);
CREATE INDEX messages_channel_created ON messages(channel_id,created_at DESC);
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, uploader_id uuid NOT NULL REFERENCES users(id), object_key text UNIQUE NOT NULL, original_filename text NOT NULL, content_type text NOT NULL CHECK(content_type IN ('video/mp4','video/webm')), byte_size bigint NOT NULL CHECK(byte_size>0), duration_seconds numeric(10,3), width integer, height integer, status media_status NOT NULL DEFAULT 'pending', moderation_note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE theater_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid NOT NULL REFERENCES channels(id) ON DELETE CASCADE, media_id uuid REFERENCES media_assets(id) ON DELETE SET NULL, host_id uuid NOT NULL REFERENCES users(id), is_playing boolean NOT NULL DEFAULT false, position_seconds numeric(12,3) NOT NULL DEFAULT 0 CHECK(position_seconds>=0), playback_rate numeric(4,3) NOT NULL DEFAULT 1 CHECK(playback_rate BETWEEN .5 AND 2), revision bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE theater_chat_timestamps (message_id uuid PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE, media_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE, timestamp_seconds numeric(12,3) NOT NULL CHECK(timestamp_seconds>=0));
CREATE TABLE guild_badge_verifications (guild_id uuid PRIMARY KEY REFERENCES guilds(id) ON DELETE CASCADE, tier badge_tier NOT NULL DEFAULT 'wood', eligible_member_count integer NOT NULL DEFAULT 0 CHECK(eligible_member_count>=0), verified_at timestamptz NOT NULL DEFAULT now(), verification_source text NOT NULL DEFAULT 'database_membership');
CREATE TABLE audit_events (id bigserial PRIMARY KEY, guild_id uuid REFERENCES guilds(id) ON DELETE SET NULL, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, event_type varchar(80) NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION kinetiq_badge_tier(member_count integer) RETURNS badge_tier LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT CASE WHEN member_count>=10000 THEN 'diamond'::badge_tier WHEN member_count>=5000 THEN 'gold'::badge_tier WHEN member_count>=1000 THEN 'iron'::badge_tier WHEN member_count>=500 THEN 'stone'::badge_tier ELSE 'wood'::badge_tier END; $$;
